CREATE TABLE `collection_console_views` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_filter_id` CHAR(36) CHARACTER SET ascii NULL,`workspace_filter_id` CHAR(36) CHARACTER SET ascii NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`observed_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_collection_console_actor_time`(`actor_id`,`observed_at`),KEY `idx_collection_console_scope_time`(`organization_filter_id`,`workspace_filter_id`,`observed_at`),CONSTRAINT `fk_collection_console_actor` FOREIGN KEY(`actor_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
